"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Kbd } from "../kbd/kbd";

/** Props for overlay hints item. */
export interface OverlayHintsItemProps extends Omit<ComponentProps<"span">, "children"> {
  /** Key names rendered as Kbd chips, in press order. */
  keys: string[];
  /**
   * Marks the hint as useful without a keyboard. Unmarked items are hidden at
   * coarse pointer, and a bar where nothing survives collapses entirely.
   */
  touch?: boolean;
  /** What the keys do. */
  children: ReactNode;
  /** Size of the rendered Kbd chips. */
  size?: "sm" | "md";
}

/** One key group plus its label. */
function OverlayHintsItem({
  keys,
  touch = false,
  size = "md",
  children,
  className,
  ...rest
}: OverlayHintsItemProps) {
  return (
    <span
      {...rest}
      data-slot="overlay-hints-item"
      data-touch={touch ? "" : undefined}
      className={className}
    >
      {keys.map((key) => (
        <Kbd key={key} size={size}>
          {key}
        </Kbd>
      ))}
      <span>{children}</span>
    </span>
  );
}

/** Props for overlay hints. */
export interface OverlayHintsProps extends ComponentProps<"div"> {
  /** OverlayHints.Item children. */
  children: ReactNode;
}

/**
 * Keyed legend for a keyboard surface — the one piece of chrome that says the
 * product is keyboard-first, so every overlay spells it the same way.
 *
 * Hidden from assistive technology by default: the shortcuts are already
 * reachable through the real controls and their `aria-keyshortcuts`, and
 * announcing "↑ ↓ Navigate" inside a listbox is noise. Pass
 * `aria-hidden={false}` when the key names should be discoverable by AT.
 */
export function OverlayHintsRoot({
  children,
  className,
  "aria-hidden": ariaHidden = true,
  ...rest
}: OverlayHintsProps) {
  return (
    <div
      {...rest}
      aria-hidden={ariaHidden}
      data-slot="overlay-hints"
      className={cn("text-xs", className)}
    >
      {children}
    </div>
  );
}

export const OverlayHints = Object.assign(OverlayHintsRoot, { Item: OverlayHintsItem });

/*
 * OverlayHints — the keyed legend a keyboard-first overlay uses to teach its
 * keys. One layout, one collapse rule, one place to change touch behaviour.
 * The host surface owns its own separator and padding; this file owns only the
 * row itself, so a hint bar never doubles the hairline it sits behind.
 */
@layer components {
  [data-slot="overlay-hints"] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    min-width: 0;
    /* Wrap to a second row rather than scrolling horizontally: at 390 a fourth
       hint no longer fits on one line. */
    gap: 4px 16px;
  }

  [data-slot="overlay-hints-item"] {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--muted-foreground);
  }

  /*
   * Touch has no keyboard, so a key legend is instructions the user cannot
   * follow. Items are hidden unless the consumer marked them touch-relevant,
   * and a bar with nothing left collapses entirely rather than leaving an empty
   * strip — that recovers a full row of a 390-wide overlay.
   */
  @media (pointer: coarse) {
    [data-slot="overlay-hints"][aria-hidden="true"]
      [data-slot="overlay-hints-item"]:not([data-touch]) {
      display: none;
    }

    [data-slot="overlay-hints"][aria-hidden="true"]:not(:has([data-touch])) {
      display: none;
    }

    /* Collapsing the bar is not enough: a host chrome row whose only content is
       that collapsed bar keeps painting its border, padding and background — a
       dead 17px strip under the CommandPalette list at 390. The row that exists
       solely to hold the legend goes with it, once, here. The two :has() calls
       stay siblings on purpose — :has() inside :has() is invalid and drops the
       whole rule. */
    :has(> [data-slot="overlay-hints"][aria-hidden="true"]:only-child):not(:has([data-touch])) {
      display: none;
    }

    /* A legend the consumer deliberately exposed to AT (Dialog) is the only
       place its shortcut is announced, and touch screen readers exist — so it
       leaves the visual flow, not the accessibility tree. Absolutely positioned
       content reserves no height, so a bar whose items all went out of flow
       paints exactly like the display:none case above, and the host row that
       exists only to hold it collapses the same way. */
    [data-slot="overlay-hints"][aria-hidden="false"]
      [data-slot="overlay-hints-item"]:not([data-touch]),
    :has(> [data-slot="overlay-hints"][aria-hidden="false"]:only-child):not(:has([data-touch])) {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }
  }
}
